// Pascal's triangle as a recurrence table. Coordinates are in the same pixel-like
// range as size(), so labels keep their intended weight in the rendered figure.
size(360,300);
pen rule = black + 0.8;
label("$1$", (0,40));
label("$1$", (-35,92));
label("$1$", (35,92));
label("$1$", (-70,144));
label("$2$", (0,144));
label("$1$", (70,144));
label("$1$", (-105,196));
label("$3$", (-35,196));
label("$3$", (35,196));
label("$1$", (105,196));
label("$1$", (-140,248));
label("$4$", (-70,248));
label("$6$", (0,248));
label("$4$", (70,248));
label("$1$", (140,248));
draw((-165,20)--(165,20), rule);
label("each entry $=$ the two above it", (0,14), S);
